// Transport layer (Kaizen v0).
// One job: spawn a real agent CLI, capture its output, classify success/failure.
// Every rule here is grounded in research/canary-results.md (verified locally).
// Written with node: APIs so it runs on Node 24 today and stays Bun-compatible.

import { spawn } from "node:child_process";

// Agents can think for minutes; cap wall-clock. 10m: a repo-grounded run showed
// 5m is too tight for larger evidence-gathering turns.
export const DEFAULT_TIMEOUT_MS = 10 * 60 * 1000;
const TERMINATION_GRACE_MS = 250;

export type CliCapture = { code: number | null; stdout: string; stderr: string; timedOut: boolean };

// Spawn a CLI in `cwd`. stdin is IGNORED (= </dev/null): the canary showed Codex
// hangs waiting for stdin EOF otherwise. stdout/stderr captured separately.
function runCli(cmd: string, args: string[], cwd: string, timeoutMs: number): Promise<CliCapture> {
  return new Promise((resolve) => {
    // On POSIX, detached gives this CLI its own process group. Never signal our
    // own group: workers inherit the CLI's group, whose ID is the child's PID.
    const child = spawn(cmd, args, { cwd, detached: true, stdio: ["ignore", "pipe", "pipe"] });
    let stdout = "";
    let stderr = "";
    let timedOut = false;
    let settled = false;
    let killTimer: ReturnType<typeof setTimeout> | undefined;
    const finish = (code: number | null) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      clearTimeout(killTimer);
      resolve({ code, stdout, stderr, timedOut });
    };
    const signalGroup = (signal: NodeJS.Signals) => {
      if (child.pid === undefined) return; // spawn failed; never signal group 0
      try {
        process.kill(-child.pid, signal);
      } catch (e) {
        // The group may already have exited between the deadline and signal.
        if ((e as NodeJS.ErrnoException).code !== "ESRCH") {
          stderr += `\nFailed to send ${signal} to CLI process group: ${String(e)}`;
        }
      }
    };
    const timer = setTimeout(() => {
      timedOut = true;
      signalGroup("SIGTERM");
      killTimer = setTimeout(() => {
        // Even if the leader closed, a worker may still be alive in its group.
        signalGroup("SIGKILL");
        // Completion must not depend on inherited pipes closing after a timeout.
        child.stdout.destroy();
        child.stderr.destroy();
        child.unref();
        finish(child.exitCode);
      }, TERMINATION_GRACE_MS);
    }, timeoutMs);
    child.stdout.on("data", (d) => { stdout += d.toString(); });
    child.stderr.on("data", (d) => { stderr += d.toString(); });
    child.on("error", (e) => {
      stderr = String(e);
      if (!timedOut) finish(null);
    });
    child.on("close", (code) => {
      if (!timedOut) finish(code);
    });
  });
}

